#include <iostream>
#include <string>
#include <utility>

class BankAccount {
public:
    BankAccount(std::string owner, double openingBalance)
        : owner_{std::move(owner)}, balance_{openingBalance} {}

    void deposit(double amount) {
        if (amount > 0) balance_ += amount;
    }

    bool withdraw(double amount) {
        if (amount <= 0 || amount > balance_) return false;
        balance_ -= amount;
        return true;
    }

    double balance() const { return balance_; }
    const std::string& owner() const { return owner_; }

private:
    std::string owner_;
    double balance_;
};

int main() {
    BankAccount account{"Ada", 100.0};
    account.deposit(50);
    bool ok = account.withdraw(500);

    std::cout << account.owner() << ": " << account.balance() << '\n';
    std::cout << std::boolalpha << "withdraw 500 succeeded: " << ok << '\n';
}

#include <iostream>

struct Point {          // struct: members public by default
    double x{};
    double y{};
};

class Rectangle {
public:
    Rectangle() = default;                                      // uses the member initialisers
    Rectangle(double w, double h) : width_{w}, height_{h} {}
    explicit Rectangle(double side) : Rectangle(side, side) {}  // delegates to the one above

    double area() const { return width_ * height_; }
    void scale(double factor) { width_ *= factor; height_ *= factor; }

private:
    double width_{1.0};
    double height_{1.0};
};

int main() {
    Point p{3.0, 4.0};
    std::cout << "p = (" << p.x << ", " << p.y << ")\n";

    Rectangle unit;
    Rectangle r{2.0, 3.5};
    Rectangle square{4.0};

    r.scale(2);
    std::cout << unit.area() << ' ' << r.area() << ' ' << square.area() << '\n';
}

#include <iostream>

class Counter {
public:
    Counter() { ++instances_; }
    ~Counter() { --instances_; }     // destructor: runs when the object dies

    Counter(const Counter&) = delete;            // copying would corrupt the count,
    Counter& operator=(const Counter&) = delete; // so forbid it

    static int instances() { return instances_; }

private:
    static inline int instances_{0};  // one shared value for the whole class
};

int main() {
    Counter a;
    std::cout << Counter::instances() << '\n';
    {
        Counter b;
        Counter c;
        std::cout << Counter::instances() << '\n';
    }   // b and c are destroyed here, in reverse order of creation
    std::cout << Counter::instances() << '\n';
}

#include <iostream>

struct Money {
    long long cents{};

    Money operator+(Money other) const { return Money{cents + other.cents}; }
    bool operator==(const Money&) const = default;   // C++20: compares every member
};

std::ostream& operator<<(std::ostream& out, Money m) {
    return out << m.cents / 100 << '.' << (m.cents % 100 < 10 ? "0" : "") << m.cents % 100;
}

int main() {
    Money price{1999};
    Money tax{205};
    Money total = price + tax;

    std::cout << total << '\n';
    std::cout << std::boolalpha << (total == Money{2204}) << '\n';
}
